 "content": "def transform(grid):
    """Project each horizontal color-run template onto isolated matching markers."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    templates = []
    template_cells = set()
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            if c - start >= 2:
                seq = row[start:c]
                templates.append((r, start, seq))
                template_cells.update((r, j) for j in range(start, c))
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in template_cells:
                continue
            matches = [seq for _, _, seq in templates if color in seq]
            if not matches:
                continue
            # Template colors identify their sequence; if duplicated, prefer the shortest.
            seq = min(matches, key=len)
            index = seq.index(color)
            start = c - index
            for j, value in enumerate(seq):
                cc = start + j
                if 0 <= cc < w:
                    out[r][cc] = value
    return out
